// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // Drive a call to setOwner
        (bool success, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", _owner));
        // The reference satisfies: if call succeeds, owner changes to _owner; buggy version leaves owner unchanged
        assertTrue(success == false || c.owner() == _owner);
    }
}

